/**
 * AttentionHeatmap.js - Attention Weight Visualization
 * Week 2 - Days 10-14
 */

import React from 'react';
import { motion } from 'framer-motion';

const AttentionHeatmap = ({ days }) => {
  const maxImportance = Math.max(...days.map(d => d.importance));

  return (
    <motion.div
      className="attention-heatmap-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.7 }}
    >
      <h3 className="card-title">
        <span>👁️</span>
        <span>Important Historical Days</span>
      </h3>

      <div className="day-list">
        {days.map((day, index) => {
          const percentage = (day.importance / maxImportance) * 100;

          return (
            <motion.div
              key={day.day_index}
              className="day-item"
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: 0.8 + index * 0.1 }}
            >
              <div className="day-rank">#{index + 1}</div>
              
              <div className="day-info">
                <div className="day-label">
                  {day.days_ago === 0 ? 'Today' : `${day.days_ago} days ago`}
                </div>
                <div className="day-importance">
                  Importance: {day.importance.toFixed(3)}
                </div>
              </div>

              <div className="day-bar">
                <motion.div
                  className="day-bar-fill"
                  initial={{ width: 0 }}
                  animate={{ width: `${percentage}%` }}
                  transition={{ duration: 0.8, delay: 0.9 + index * 0.1 }}
                />
              </div>
            </motion.div>
          );
        })}
      </div>

      <div style={{ marginTop: 'var(--spacing-md)', padding: 'var(--spacing-sm)', background: 'var(--bg-dark)', borderRadius: '8px', fontSize: '0.875rem', color: 'var(--text-muted)' }}>
        <strong>💡 Tip:</strong> The model pays more attention to these specific days when making predictions. Recent days typically have higher importance.
      </div>
    </motion.div>
  );
};

export default AttentionHeatmap;
